use @piton/config
use @piton/belay

from @piton/belay import ClaudeAdapter

export piton-config Project:
    root: ./spec
    entry: ./spec/index.pi

    frameworks:
        - {BelayConfiguration}

belay-config BelayConfiguration:
    codeRoot: ./src
    shapeRoot: ./spec/shape

    adapters:
        - {ClaudeAdapter}
Compile Piton (.pi) source into data, or into agentic Markdown through a framework such as Belay.

Usage: piton <COMMAND>

Commands:
  compile  Compile Piton files into data
  check    Check Piton files, or the whole project, without writing anything
  build    Build the project described by piton.config.pi
  reach    List which files under the project root are compiled, and which are not
  loc      Count lines, separating prose from structure
  format   Apply the canonical formatting
  lsp      Run the language server over stdio
  grammar  Generate editor grammars and extensions
  docs     Print the generated language reference
  claude   Start the Claude CLI with Piton and framework fluency preloaded
  ast      Print a file's concrete syntax tree
  help     Print this message or the help of the given subcommand(s)

Options:
  -h, --help
          Print help (see a summary with '-h')

  -V, --version
          Print version
    save_in(&asks_dir(project_dir), anchor, prompt)
}

fn save_in(dir: &Path, anchor: &HiddenAnchor, prompt: &str) -> Result<PathBuf> {
    fs::create_dir_all(dir).with_context(|| format!("could not create {}", dir.display()))?;
    let sent_at = SystemTime::now()
        .duration_since(UNIX_EPOCH)
        .map_or(0, |elapsed| elapsed.as_secs());
    let file = dir.join(format!("{sent_at}-{}.pi", anchor.name));
    fs::write(&file, anchor.source(prompt))
        .with_context(|| format!("could not save {}", file.display()))?;
    Ok(file)
}

/// Compiles `file`, a saved `anchor`, and returns its compiled prompt text.
pub fn compile(anchor: &HiddenAnchor, file: &Path, project_dir: &Path) -> Result<CompiledPrompt> {
    let output = Command::new("piton")
        .args(["compile", "--stdout"])
        .arg(file)
        .current_dir(project_dir)
        .output()
        .context("could not run `piton compile`")?;
    if !output.status.success() {
        let mut message = String::from_utf8_lossy(&output.stdout).into_owned();
        message.push_str(&String::from_utf8_lossy(&output.stderr));
        return Err(anyhow!("{}", message.trim()));
    }

    let compiled: Value =
        serde_json::from_slice(&output.stdout).context("`piton compile` did not print JSON")?;
    let compiled = compiled
        .get(&anchor.name)
        .ok_or_else(|| anyhow!("the compiled output has no {}", anchor.name))?;
    let user_prompt = compiled
        .get("userPrompt")
        .ok_or_else(|| anyhow!("the compiled anchor has no userPrompt"))?;
    // Each piece of attached text compiles to the list of its lines.
    let attached_text: Vec<String> = compiled
        .get("attachedText")
        .and_then(Value::as_array)
        .map(|pieces| {
            pieces
                .iter()
                .map(|piece| match piece {
                    Value::Array(lines) => lines
                        .iter()
                        .map(|line| line.as_str().unwrap_or_default())
                        .collect::<Vec<_>>()
                        .join("\n"),
                    other => prose(other),
                })

